const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

window.__ensemble.setState({ capacity: { more: 14, mb: 560, core: 0.05, coreMeasured: true, measured: true, text: 'This computer can carry about 14 more agents now (about 560 MB and 5% of a core each, measured).' } });
window.__ensemble.getState().setModal({ kind: 'settings' });
await new Promise(r => setTimeout(r, 700));
const p = [...document.querySelectorAll('[role=dialog] p')].find(x => /can carry about/.test(x.textContent));
p && p.scrollIntoView({ block: 'center' });
await new Promise(r => setTimeout(r, 300));
return 'line shown: ' + !!p;

window.__ensemble.getState().setModal(null); window.__ensemble.setState({ capacity: null }); await new Promise(r => setTimeout(r, 300));
window.__ensemble.getState().setModal({ kind: 'settings' }); await new Promise(r => setTimeout(r, 700));
return 'without capacity, line shown: ' + !![...document.querySelectorAll('[role=dialog] p')].find(x => /can carry about/.test(x.textContent));
